#!/usr/bin/env python3
import argparse,json,sys,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];sys.path.insert(0,str(ROOT/'tools'))
from claim_registry import load,write_json,validate
from claim_reviews import Evidence,make_review,claim_digest
p=argparse.ArgumentParser();p.add_argument('--out',type=Path,required=True);a=p.parse_args();d=load();rev=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip();E=Evidence()
report='results/parallel_index_significance_normalizers/AUDIT.md';sources='results/parallel_index_significance_normalizers/sources.json'
rows=[
('thm:odd-affine-Booleanity-classification','general_tool','Useful odd-field truncated-ideal classification. Related real permutation/matching degree-one classifications are established, but they do not directly identify this weak-PHP certificate criterion; exact novelty is unresolved.', ['https://arxiv.org/pdf/1011.3342','https://yuvalfilmus.cs.technion.ac.il/Papers/measures.pdf'],'If later proposed for publication, compare the odd-field degree-two weak-row ideal criterion explicitly against finite-characteristic degree-one classifications; pointwise permutation Booleanity is a different hypothesis.'),
('thm:reduced-product-Booleanity-PC-NS-gap','general_tool','Exact ENS consequence-degree example clarifies original companion activity and static versus dynamic certificate costs. General PC/NS degree separation is classical; originality of this restricted exact formula is unresolved.', ['https://www.cs.utoronto.ca/~toni/Papers/homo-icalp.pdf'],'Use as an exact accounting counterexample. If publication is considered, compare consequence-target examples retaining original generator degree after input reduction, rather than claiming a new PC/NS separation phenomenon.'),
('thm:PHP-reduced-product-Booleanity-gap','general_tool','Residual-design argument preserves the exact ENS Booleanity-degree example over sufficiently large full weak PHP. It is a scoped strengthening of the preceding accounting tool, not a new general PC/NS separation.', ['https://www.cs.utoronto.ca/~toni/Papers/homo-icalp.pdf','https://eccc.weizmann.ac.il/report/2020/001/'],'If disseminated separately, compare target-degree lower bounds under independent residual designs and retain the sufficient board bound and original companion degree; do not promote the longstanding separation phenomenon as new.'),
('thm:ternary-coefficient-degree-frontier','general_tool','Exact independent-column coefficient-degree frontier uses established grid-selector degree techniques; its constant-coefficient case is classical covering and its positive-degree formulation is a special case of the recorded heterogeneous frontier.', ['https://community.middlebury.edu/~jschmitt/papers/on_zeros_of_a_polynomial_in_a_finite_grid.pdf'],'Treat as a specialization of the heterogeneous candidate in any publication assessment; preserve encoded coordinate degree and the exclusion of PHP row equations.'),
('thm:heterogeneous-scalar-profile-frontier','independent_result','Potential independent exact frontier for polynomial-coefficient ENS factors in independent encoded scalar profiles. Constant coefficients recover classical finite-grid covering; the positive-degree occurrence-budget refinement was not identified in the targeted primary comparison, so novelty remains unknown.', ['https://community.middlebury.edu/~jschmitt/papers/on_zeros_of_a_polynomial_in_a_finite_grid.pdf'],'Before promotion, obtain a finite-grid-covering expert comparison of the positive-T encoded-coordinate factor model and its untouched-group budget; distinguish native scalar degree and the already known T=0 case.')]
out=[]
for label,category,rationale,urls,action in rows:
 c=next(c for c in d['claims'] if c['id']==label);refs=list(dict.fromkeys(c['significance']['references']+[report,sources]+urls))
 value={'category':category,'rationale':rationale,'novelty':'unknown','publication_status':'candidate' if category=='independent_result' else 'not_applicable','references':refs,'next_action':action}
 c['significance']=value
 targets=[x['target'] for x in c['reviews']['significance']['evidence']]+[report,sources]
 review=make_review(d,c,'significance',targets,revision=rev,date='2026-09-19',reviewer='Codex parallel significance audit',note='Completed targeted primary-literature comparison and exact local scope review. Unknown novelty is an assessed residual uncertainty, not an unperformed-audit placeholder; see the source-backed report.',state='reviewed',next_action=None,evidence=E)
 c['reviews']['significance']=review
 out.append({'id':label,'baseline_claim_sha256':claim_digest(c),'fields':{'significance':value},'reviews':{'significance':review}})
validate(d);write_json(a.out,{'schema_version':1,'baseline_revision':rev,'scope':'Five completed source-relative significance assessments; no canonical edits or new proof audit.','claims':out,'counts':{'reviewed':5,'novelty_unknown':5,'publication_candidates':1}});print('Five reviewed significance proposals; exact novelty remains unknown; one candidate retained.')
